Scoring Engine Container.diagram:
@startuml
!include https://raw.githubusercontent.com/plantuml-stdlib/C4-PlantUML/master/C4_Component.puml
LAYOUT_WITH_LEGEND()

Container_Boundary(scoring_engine_container, "Scoring Engine Container") {
    Component(Fraud_Scoring_Controller, "Fraud Scoring Controller", "AWS ECS Fargate / Python REST API", "Receives incoming scoring requests from the API Gateway and coordinates the evaluation pipeline.")
    Component(Model_Inference_Client, "Model Inference Client", "AWS SDK", "Invokes the SageMaker Real-Time Endpoint over VPC interface endpoints to execute fraud scoring logic.")
    Component(Audit_Log_Dispatcher, "Audit Log Dispatcher", "AWS SDK with AWS KMS", "Offloads decision logs asynchronously to Amazon SQS with encryption to guarantee 7-year auditability.")
}

Rel(Fraud_Scoring_Controller, Model_Inference_Client, "Invokes model inference", "AWS SDK over VPC interface endpoints")
Rel(Fraud_Scoring_Controller, Audit_Log_Dispatcher, "Offloads audit logs asynchronously", "AWS SDK with AWS KMS encryption")

@enduml

AWS SageMaker Serverless Inference.diagram:
@startuml
!include https://raw.githubusercontent.com/plantuml-stdlib/C4-PlantUML/master/C4_Component.puml
LAYOUT_WITH_LEGEND()

Container_Boundary("AWS_SageMaker_Serverless_Inference", "AWS SageMaker Serverless Inference") {
    Component(Model_Inference_Runtime, "Model Inference Runtime", "AWS ECS Fargate running ONNX", "Invokes high-performance, low-latency fraud scoring without cold-start penalties.")
}

System(Scoring_Engine_Container, "Scoring Engine Container", "AWS ECS Fargate")

Rel(Scoring_Engine_Container, Model_Inference_Runtime, "Invokes fraud scoring", "gRPC / Internal Network")

@enduml

Amazon Aurora Serverless.diagram:
@startuml
!include https://raw.githubusercontent.com/plantuml-stdlib/C4-PlantUML/master/C4_Component.puml
LAYOUT_WITH_LEGEND()

title Component diagram for the Amazon Aurora Serverless container

Container_Boundary(aurora_serverless, "Amazon Aurora Serverless") {
    Component(Case_Data_Store, "Case Data Store", "Amazon Aurora Serverless (v2)", "Relational database configured with auto-pause disabled and 0.5–8 ACUs for reading and writing review cases.")
    Component(Audit_Log_Streamer, "Audit Log Streamer", "CloudWatch Agent / KMS", "Streams advanced audit logs to Amazon CloudWatch encrypted with customer-managed keys.")
}

Rel(Case_Data_Store, Audit_Log_Streamer, "Streams advanced audit logs", "CloudWatch Agent / KMS")

@enduml

QLDB / S3 Object Lock.diagram:
@startuml
!include https://raw.githubusercontent.com/plantuml-stdlib/C4-PlantUML/master/C4_Component.puml
LAYOUT_WITH_LEGEND()

title Component diagram for the QLDB / S3 Object Lock container

Container_Boundary(ql_s3_container, "QLDB / S3 Object Lock") {
    Component(s3_object_lock_storage, "S3 Object Lock Storage", "Amazon S3 with Object Lock (Compliance Mode)", "Immutable storage guaranteeing 7-year audit retention for tamper-evident decision logs.")
    Component(aws_kms_encryption_service, "AWS KMS Encryption Service", "AWS KMS", "Provides customer-managed key encryption with locked policies for data protection.")
}

System(scoring_engine_container, "Scoring Engine Container", "AWS ECS Fargate Container")

Rel(scoring_engine_container, s3_object_lock_storage, "Writes tamper-evident decision logs", "HTTPS/AWS SDK, TLS 1.3")

@enduml
